func persistEventMetadataToState(event *agent.Event, state *strategy.SessionState) {
	// Update ModelName if provided (model is known by turn-end even on first turn)
	if event.Model != "" {
		state.ModelName = event.Model
	}
	appendEventSkillEventsToState(event, state)

	// Persist hook-provided session metrics (e.g., from Cursor hooks)
	if event.DurationMs > 0 {
		state.SessionDurationMs = event.DurationMs
	}
	// Use hook-reported turn count if available (take max); otherwise
	// increment on each TurnEnd event to count turns ourselves.
	prevTurnCount := state.SessionTurnCount
	if event.TurnCount > 0 {
		if event.TurnCount > state.SessionTurnCount {
			state.SessionTurnCount = event.TurnCount
		}
	} else if event.Type == agent.TurnEnd {
		state.SessionTurnCount++
	}
	// Deferred checkpoint-window reset: the first time the turn count actually
	// advances after a checkpoint was written, re-anchor the window base to the
	// count from before this turn so the current turn becomes the first prompt of
	// the new window. Gate on a real advance (not just a TurnEnd / non-zero
	// TurnCount) so a repeated or stale hook reporting the same cumulative count
	// doesn't re-anchor early — that would make a later back-to-back checkpoint
	// report 1 instead of matching the prior count.
	if state.SessionTurnCount > prevTurnCount && state.PromptWindowResetPending {
		state.PromptWindowBase = prevTurnCount
		state.PromptWindowResetPending = false
	}
	if event.ContextTokens > 0 {
		state.ContextTokens = event.ContextTokens
	}
	if event.ContextWindowSize > 0 {
		state.ContextWindowSize = event.ContextWindowSize
	}
}

func appendEventSkillEventsToState(event *agent.Event, state *strategy.SessionState) bool {
	if event == nil || state == nil || len(event.SkillEvents) == 0 {
		return false
	}
	changed := false
	for _, skillEvent := range event.SkillEvents {
		if skillEvent.TurnID == "" {
			skillEvent.TurnID = state.TurnID
		}
		if skillEventExists(state.SkillEvents, skillEvent) {
			continue
		}
		state.SkillEvents = append(state.SkillEvents, skillEvent)
		changed = true
	}
	return changed
}

func skillEventExists(events []agent.SkillEvent, candidate agent.SkillEvent) bool {
	for _, existing := range events {
		if existing.ID != "" && candidate.ID != "" {
			if existing.ID == candidate.ID {
				return true
			}
			continue
		}
		if existing.EventType == candidate.EventType &&
			existing.Skill.Name == candidate.Skill.Name &&
			existing.Source.Agent == candidate.Source.Agent &&
			existing.Source.Signal == candidate.Source.Signal &&
			existing.TurnID == candidate.TurnID {
			return true
		}
	}
	return false
}

// envAdoptionSpec carries the kind-specific bits of env-driven session
// tagging. The shared scaffolding (idempotence guard, SESSION/AGENT/
// STARTING_SHA gates) lives in tryAdoptEnv; apply runs only after the gates
// pass and is responsible for decoding the kind-specific payload, mutating
// state.Kind and the related fields, and emitting the success log.
type envAdoptionSpec struct {
	kindLabel      string // "review" or "investigate" — log prefix
	envSession     string
	envAgent       string
	envStartingSHA string
	apply          func(ctx context.Context, state *session.State, expectedAgent string)
}

// tryAdoptEnv runs the shared env-adoption protocol for a launched-agent
// process and delegates kind-specific decode/apply to spec.apply.
//
// The protocol:
//  1. If state.Kind is already set, do nothing — adoption is idempotent
//     across turns, and a session is review OR investigate, not both.
//  2. envSession must be "1". `entire review` / `entire investigate` set
//     this on the spawned agent process; the lifecycle hook (a child of
//     the agent) inherits it naturally.
//  3. envAgent must match the hook's agent — protects against stale env
//     vars inherited from a parent shell or a nested invocation.
//  4. envStartingSHA must match the session's BaseCommit — protects
//     against env vars surviving a commit boundary.
//
// All failures log at debug/warn and leave state untagged.
//
// Trust model: this gate (env-present + agent-match + SHA-match) treats
// the parent process environment as trusted. The CLI never exports these
// vars to a user shell — they exist only on the in-process env of agents
// spawned by `entire review` / `entire investigate` themselves, plus the
// lifecycle hook (a child of that agent) which inherits them naturally.
// A user who manually `export`s ENTIRE_REVIEW_AGENT=<their-agent> and
// ENTIRE_REVIEW_STARTING_SHA=<HEAD-sha> before launching an agent COULD
// forge a review-tagged session; that is considered out-of-scope for the
// adoption guard. The SHA gate also self-invalidates on the next commit

package cli

import (
	"context"
	"log/slog"
	"slices"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/session"
)

// sweepCondenseBudget caps how much wall clock one sweep may spend condensing,
// across all sessions it finalizes.
//
// Marking a session ENDED is a single atomic state-file rename; condensing it
// costs ~120ms at best and seconds for a large transcript. Since sessions stay
// un-finalized for up to StaleSessionThreshold (7 days), a first sweep after
// upgrade can have a large backlog, and the callers here are interactive
// commands — including `entire status --json`, which the MCP entire_status tool
// calls, where nothing prints until the sweep returns.
//
// So every candidate is always marked ended (that is what un-sticks it from
// `entire status`), while condensing runs only while the budget lasts. Skipping
// it is the same fail-open path a failed condense already takes: FullyCondensed
// stays false and PostCommit retries, with `entire doctor` reporting the session
// as "ended with uncondensed checkpoint data" in the meantime. A backlog
// therefore drains over successive invocations instead of stalling one.
const sweepCondenseBudget = time.Second

// finalizeExitedSessions finalizes every non-ended session in states whose
// owning agent process has exited (clean /exit, crash, kill, terminal close,
// reboot) without a SessionStop hook firing — ACTIVE mid-turn, or IDLE because
// the agent finished its turn before quitting. Each is finalized exactly as a
// clean session stop would be: the session-stop transition runs (PhaseEnded +
// EndedAt) and pending work is eagerly condensed, subject to
// sweepCondenseBudget.
//
// It refreshes the matched in-memory states from disk after finalizing — so
// callers can re-filter/re-render without their own reload — and returns the
// number finalized. Each session is best-effort: a failure to mark one ended is
// logged and skipped; a condense failure is logged but the session is still
// counted (PostCommit will retry the condense later).
func finalizeExitedSessions(ctx context.Context, states []*session.State) int {
	// Nothing to do is overwhelmingly the common case, and returning here keeps
	// the sweep off the logging and store setup below entirely.
	if !slices.ContainsFunc(states, (*session.State).OwnerExited) {
		return 0
	}

	// Neither caller (`entire status`, `entire doctor`) initializes logging, so
	// the phase-transition and condense lines below would land on the user's
	// terminal via slog.Default() instead of the log file. The level getter is
	// paired with it exactly as at the other command-level Init sites, or
	// `log_level` in settings would be ignored on this path.
	logging.SetLogLevelGetter(GetLogLevel)
	defer logging.EnsureInitialized(ctx)()

	logCtx := logging.WithComponent(ctx, "session")
	condenseDeadline := time.Now().Add(sweepCondenseBudget)

	var store *session.StateStore // lazily created on first finalize
	finalized := 0
	for _, st := range states {
		if !st.OwnerExited() {
			continue // cheap pre-filter on the (possibly stale) list snapshot
		}

		// Finalize via the same path a clean SessionStop hook would take, but
		// re-validate OwnerExited on the freshly-loaded state under the lock:
		// a turn may have started since the snapshot and replaced the dead
		// owner with a live one, in which case ended is false and we leave it be.
		ended, err := endSessionNow(ctx, nil, st.SessionID, func(s *session.State) bool {
			return s.OwnerExited()
		}, condenseDeadline)
		if err != nil {
			logging.Warn(logCtx, "failed to finalize exited session",
				slog.String("session_id", st.SessionID),
				slog.String("error", err.Error()))
			continue
		}
		if !ended {
			continue
		}

		// Refresh the in-memory snapshot from disk so downstream filtering and
		// doctor classification see the true post-finalize state: ended, and
		// condensed only if the eager condense actually ran and succeeded (it is
		// fail-open and budget-capped, so StepCount/FullyCondensed must not be
		// assumed). Fall back to a minimal ended-marking if the reload fails —
		// enough for the caller's "active" filter to drop it.
		if store == nil {
			if s, serr := session.NewStateStore(ctx); serr == nil {
				store = s
			}
		}
		refreshed := false
		if store != nil {
			if reloaded, lerr := store.Load(ctx, st.SessionID); lerr == nil && reloaded != nil {
				*st = *reloaded
				refreshed = true
			}
		}
		if !refreshed {
			now := time.Now()
			st.Phase = session.PhaseEnded
			st.EndedAt = &now
		}
		finalized++
	}
	return finalized
}

