11	// HookTrustGaps returns the snake_case event labels declared in
12	// <repoRoot>/.codex/hooks.json that don't have a matching
13	// `[hooks.state."<hooks.json>:<event>:0:0"]` entry in the user's Codex
14	// config.toml — i.e. events the local user hasn't approved yet.
15	//
16	// This is the structural form of the trust check: we don't recompute
17	// Codex's hook hash, we only look at key presence. That misses the
18	// "command changed but key is still there" case (status = Modified),
19	// but Codex's own startup warning catches those — our purpose here is
20	// to surface fresh additions like "you trusted three hooks last month
21	// but a new PostToolUse arrived" inside our SessionStart welcome.
22	//
23	// Returns nil when:
24	//   - .codex/hooks.json doesn't exist (entire isn't installed in this repo)
25	//   - The user's config.toml can't be read
26	//   - Every declared event already has a state entry
27	func HookTrustGaps(repoRoot string) []string {
28		hooksJSONPath := filepath.Join(repoRoot, ".codex", "hooks.json")
29		declared, ok := declaredCodexEvents(hooksJSONPath)
30		if !ok || len(declared) == 0 {
31			return nil
32		}
33	
34		configPath := codexConfigPath()
35		if configPath == "" {
36			return nil
37		}
38		trusted, ok := readCodexTrustedKeys(configPath)
39		if !ok {
40			return nil
41		}
42	
43		var gaps []string
44		for _, ev := range declared {
45			// Match any handler index — Codex's state key is
46			// "<path>:<event>:<group>:<handler>". Trust on any handler counts.
47			prefix := hooksJSONPath + ":" + ev + ":"
48			if !codexAnyKeyHasPrefix(trusted, prefix) {
49				gaps = append(gaps, ev)
50			}
51		}
52		return gaps
53	}
54	
55	func codexConfigPath() string {
56		if h := os.Getenv("CODEX_HOME"); h != "" {
57			return filepath.Join(h, "config.toml")
58		}
59		home, err := os.UserHomeDir()
60		if err != nil {
61			return ""
62		}
63		return filepath.Join(home, ".codex", "config.toml")
64	}
65	
66	// declaredCodexEvents reads hooks.json and returns the snake_case labels
67	// of every event that has at least one handler declared. The bool reports
68	// whether the read+parse succeeded — false on missing/malformed file so
69	// callers can stay silent rather than mid-flow noise.
70	func declaredCodexEvents(hooksJSONPath string) ([]string, bool) {
71		data, err := os.ReadFile(hooksJSONPath) //nolint:gosec // path constructed from caller-controlled repo root
72		if err != nil {
73			return nil, false
74		}
75		var file HooksFile
76		if err := json.Unmarshal(data, &file); err != nil {
77			return nil, false
78		}
79		var events []string
80		add := func(label string, groups []MatcherGroup) {
81			for _, g := range groups {
82				if len(g.Hooks) > 0 {
83					events = append(events, label)
84					return
85				}
86			}
87		}
88		add("session_start", file.Hooks.SessionStart)
89		add("user_prompt_submit", file.Hooks.UserPromptSubmit)
90		add("stop", file.Hooks.Stop)
91		add("pre_tool_use", file.Hooks.PreToolUse)
92		add("post_tool_use", file.Hooks.PostToolUse)
93		return events, true
94	}
95	
96	// MissingEntireHooks returns the snake_case event labels the CLI's
97	// canonical install ships today (SessionStart, UserPromptSubmit, Stop,
98	// PostToolUse) that aren't backed by an Entire-managed hook command in
99	// <repoRoot>/.codex/hooks.json. Surfaces drift when the user enabled
100	// Codex on an older release and the install set has since grown.
101	//
102	// Returns nil when hooks.json is missing or unreadable — those cases
103	// are "Codex isn't enabled here", which is a different problem.
104	func MissingEntireHooks(repoRoot string) []string {
105		hooksJSONPath := filepath.Join(repoRoot, ".codex", "hooks.json")
106		data, err := os.ReadFile(hooksJSONPath) //nolint:gosec // path constructed from caller-controlled repo root
107		if err != nil {
108			return nil
109		}
110		var file HooksFile
111		if err := json.Unmarshal(data, &file); err != nil {
112			return nil
113		}
114		var missing []string
115		check := func(label string, groups []MatcherGroup) {
116			if !hasEntireHook(groups) {
117				missing = append(missing, label)
118			}
119		}
120		check("session_start", file.Hooks.SessionStart)
121		check("user_prompt_submit", file.Hooks.UserPromptSubmit)
122		check("stop", file.Hooks.Stop)
123		check("post_tool_use", file.Hooks.PostToolUse)
124		return missing
125	}
126	
127	// codexTrustStateHeaderRegex matches `[hooks.state."<key>"]` headers in
128	// the user's Codex config.toml. Quote-only — Codex's own writer emits
129	// quoted keys (codex-rs/tui/src/app/background_requests.rs:874), and
130	// looser parsing would invite false matches in user-edited configs.
131	var codexTrustStateHeaderRegex = regexp.MustCompile(`(?m)^\[hooks\.state\."([^"]+)"\]`)
132	
133	func readCodexTrustedKeys(configPath string) (map[string]struct{}, bool) {
134		data, err := os.ReadFile(configPath) //nolint:gosec // path resolved from CODEX_HOME or HOME
135		if err != nil {
136			return nil, false
137		}
138		keys := make(map[string]struct{})
139		for _, m := range codexTrustStateHeaderRegex.FindAllStringSubmatch(string(data), -1) {
140			keys[m[1]] = struct{}{}
141		}
142		return keys, true
143	}
144	
145	func codexAnyKeyHasPrefix(keys map[string]struct{}, prefix string) bool {
146		for k := range keys {
147			if strings.HasPrefix(k, prefix) {
148				return true
149			}
150		}
151		return false
152	}
